import { describe, expect, it } from 'vitest'
import {
  evaluateGeometryObservation,
  GeometryEvaluationError,
  GEOMETRY_HOMOGRAPHY_TYPE_CV_64F,
  GEOMETRY_MASK_TYPE_CV_8U,
  type GeometryHomographyObservation,
  type GeometryMaskObservation,
  type GeometryObservationInput,
  type GeometryPixelPoint,
} from '../src/scan/geometryEvaluation'

/**
 * Vectors are hand-computed from the native evaluateGeometry math (T331 map /
 * T331 lead-decision). They are native-SOURCE anchors + closed-form values,
 * NOT results generated by this implementation and NOT an OpenCV/Android run.
 */

const CV_64F = GEOMETRY_HOMOGRAPHY_TYPE_CV_64F
const CV_8U = GEOMETRY_MASK_TYPE_CV_8U

function homography(
  values: readonly number[] | null,
  overrides: Partial<GeometryHomographyObservation> = {},
): GeometryHomographyObservation {
  return { empty: false, rows: 3, cols: 3, type: CV_64F, values, ...overrides }
}

function mask(
  bytes: readonly number[] | null,
  overrides: Partial<GeometryMaskObservation> = {},
): GeometryMaskObservation {
  const length = bytes === null ? 0 : bytes.length
  return { empty: false, rows: length, cols: 1, type: CV_8U, bytes, ...overrides }
}

function point(x: number, y: number): GeometryPixelPoint {
  return { x, y }
}

const TRANSLATION = [1, 0, 17, 0, 1, 11, 0, 0, 1] as const
const IDENTITY = [1, 0, 0, 0, 1, 0, 0, 0, 1] as const

const GRID_REFERENCE = [
  point(30, 20),
  point(160, 20),
  point(290, 20),
  point(30, 180),
  point(160, 180),
  point(290, 180),
]

function observation(overrides: Partial<GeometryObservationInput> = {}): GeometryObservationInput {
  const referencePoints = overrides.referencePoints ?? GRID_REFERENCE
  return {
    referencePoints,
    queryPoints: overrides.queryPoints ?? referencePoints.map((p) => point(p.x + 17, p.y + 11)),
    referenceWidthPx: 320,
    referenceHeightPx: 200,
    homography: overrides.homography ?? homography(TRANSLATION),
    mask: overrides.mask ?? mask([1, 1, 1, 1, 1, 1]),
  }
}

describe('T333 pure geometry evaluation — accepted path', () => {
  it('accepts the translated grid with exact diagnostics (H +17/+11, zero error)', () => {
    const result = evaluateGeometryObservation(observation())
    expect(result.found).toBe(true)
    expect(result.accepted).toBe(true)
    expect(result.failure).toBe('NONE')
    expect(result.inlierIndices).toEqual([0, 1, 2, 3, 4, 5])
    expect(result.inlierRatio).toBe(1)
    expect(result.medianErrorPx).toBe(0)
    // hull of the six ref inliers = 260x160 over 320x200
    expect(result.referenceCoverage).toBeCloseTo((260 * 160) / (320 * 200), 12)
    // projected axis-aligned bounding box of reference inliers
    expect(result.supportAreaPx2).toBeCloseTo(260 * 160, 9)
    expect(result.supportEdgeRatio).toBeCloseTo(260 / 160, 12)
    expect(result.matrix).toEqual([...TRANSLATION])
  })

  it('treats nonzero mask bytes (not only 1) as inliers', () => {
    const result = evaluateGeometryObservation(observation({ mask: mask([2, 2, 2, 2, 2, 2]) }))
    expect(result.accepted).toBe(true)
    expect(result.inlierIndices).toHaveLength(6)
  })

  it('accepts a 1xN mask row shape', () => {
    const result = evaluateGeometryObservation(observation({ mask: mask([1, 1, 1, 1, 1, 1], { rows: 1, cols: 6 }) }))
    expect(result.accepted).toBe(true)
    expect(result.inlierIndices).toHaveLength(6)
  })

  it('is deterministic and never mutates caller inputs', () => {
    const reference = GRID_REFERENCE.map((p) => point(p.x, p.y))
    const query = reference.map((p) => point(p.x + 17, p.y + 11))
    const maskBytes = [1, 1, 1, 1, 1, 1]
    const input = observation({ referencePoints: reference, queryPoints: query, mask: mask(maskBytes) })
    const snapshot = JSON.stringify(input)
    const first = evaluateGeometryObservation(input)
    const second = evaluateGeometryObservation(input)
    expect(first).toEqual(second)
    expect(JSON.stringify(input)).toBe(snapshot)
  })
})

describe('T333 homography refusals', () => {
  it('reports empty homography as HOMOGRAPHY_EMPTY with found=false', () => {
    const result = evaluateGeometryObservation(observation({ homography: homography(null, { empty: true }) }))
    expect(result.failure).toBe('HOMOGRAPHY_EMPTY')
    expect(result.found).toBe(false)
    expect(result.accepted).toBe(false)
    expect(result.matrix).toBeNull()
  })

  it('reports wrong 3x3, wrong type, unreadable cells, and non-finite as INVALID_HOMOGRAPHY', () => {
    const wrongShape = evaluateGeometryObservation(observation({ homography: homography([...TRANSLATION], { rows: 2 }) }))
    expect(wrongShape.failure).toBe('INVALID_HOMOGRAPHY')
    expect(wrongShape.found).toBe(true)
    expect(wrongShape.matrix).toBeNull()

    const wrongType = evaluateGeometryObservation(observation({ homography: homography([...TRANSLATION], { type: 5 }) }))
    expect(wrongType.failure).toBe('INVALID_HOMOGRAPHY')
    expect(wrongType.matrix).toBeNull()

    const unreadable = evaluateGeometryObservation(observation({ homography: homography(null) }))
    expect(unreadable.failure).toBe('INVALID_HOMOGRAPHY')

    const nonFinite = evaluateGeometryObservation(observation({ homography: homography([1, 0, NaN, 0, 1, 11, 0, 0, 1]) }))
    expect(nonFinite.failure).toBe('INVALID_HOMOGRAPHY')
  })
})

describe('T333 mask refusals', () => {
  it('rejects empty, wrong type, wrong count, and wrong shape as INVALID_MASK with matrix retained', () => {
    const empty = evaluateGeometryObservation(observation({ mask: mask([1, 1, 1, 1, 1, 1], { empty: true }) }))
    expect(empty.failure).toBe('INVALID_MASK')
    expect(empty.found).toBe(true)
    expect(empty.matrix).toEqual([...TRANSLATION])

    const wrongType = evaluateGeometryObservation(observation({ mask: mask([1, 1, 1, 1, 1, 1], { type: 1 }) }))
    expect(wrongType.failure).toBe('INVALID_MASK')

    const wrongCount = evaluateGeometryObservation(observation({ mask: mask([1, 1, 1, 1, 1]) }))
    expect(wrongCount.failure).toBe('INVALID_MASK')

    const wrongShape = evaluateGeometryObservation(observation({ mask: mask([1, 1, 1, 1, 1, 1], { rows: 2, cols: 3 }) }))
    expect(wrongShape.failure).toBe('INVALID_MASK')
  })
})

describe('T333 inliers, projection, support', () => {
  it('reports INSUFFICIENT_INLIERS below 4 mask inliers with observed scalars', () => {
    const result = evaluateGeometryObservation(observation({ mask: mask([1, 1, 1, 0, 0, 0]) }))
    expect(result.failure).toBe('INSUFFICIENT_INLIERS')
    expect(result.found).toBe(true)
    expect(result.accepted).toBe(false)
    expect(result.inlierIndices).toEqual([0, 1, 2])
    expect(result.inlierRatio).toBe(0.5)
    expect(result.supportAreaPx2).toBe(0)
    expect(result.supportEdgeRatio).toBe(0)
    expect(result.matrix).toHaveLength(9)
  })

  it('refuses w==0 projections as INVALID_PROJECTED_SUPPORT', () => {
    const result = evaluateGeometryObservation(
      observation({ homography: homography([1, 0, 0, 0, 1, 0, 0, 0, 0]) }),
    )
    expect(result.failure).toBe('INVALID_PROJECTED_SUPPORT')
    expect(result.found).toBe(true)
    expect(result.referenceCoverage).toBe(-1)
    expect(result.medianErrorPx).toBe(-1)
  })

  it('rejects a reflected (negative signed area) support and keeps observed magnitudes', () => {
    const reference = [point(30, 20), point(90, 20), point(90, 80), point(30, 80)]
    const result = evaluateGeometryObservation({
      referencePoints: reference,
      queryPoints: reference.map((p) => point(p.x, p.y)),
      referenceWidthPx: 100,
      referenceHeightPx: 100,
      homography: homography([1, 0, 0, 0, -1, 0, 0, 0, 1]),
      mask: mask([1, 1, 1, 1]),
    })
    expect(result.failure).toBe('INVALID_PROJECTED_SUPPORT')
    expect(result.supportAreaPx2).toBeCloseTo(3600, 9)
    // 60x60 square under a pure reflection keeps equal edges
    expect(result.supportEdgeRatio).toBeCloseTo(1, 12)
  })

  it('rejects a degenerate (collinear) support as INVALID_PROJECTED_SUPPORT', () => {
    const reference = [point(30, 20), point(90, 20), point(150, 20), point(210, 20)]
    const result = evaluateGeometryObservation({
      referencePoints: reference,
      queryPoints: reference.map((p) => point(p.x, p.y)),
      referenceWidthPx: 320,
      referenceHeightPx: 200,
      homography: homography(IDENTITY),
      mask: mask([1, 1, 1, 1]),
    })
    expect(result.failure).toBe('INVALID_PROJECTED_SUPPORT')
  })

  it('reports SUPPORT_TOO_SMALL below the 300 px^2 technical area', () => {
    const reference = [point(30, 20), point(40, 20), point(40, 30), point(30, 30)]
    const result = evaluateGeometryObservation({
      referencePoints: reference,
      queryPoints: reference.map((p) => point(p.x, p.y)),
      referenceWidthPx: 100,
      referenceHeightPx: 100,
      homography: homography(IDENTITY),
      mask: mask([1, 1, 1, 1]),
    })
    expect(result.failure).toBe('SUPPORT_TOO_SMALL')
    expect(result.supportAreaPx2).toBeCloseTo(100, 9)
  })

  it('reports SUPPORT_EDGE_RATIO above 8', () => {
    const reference = [point(30, 20), point(330, 20), point(330, 30), point(30, 30)]
    const result = evaluateGeometryObservation({
      referencePoints: reference,
      queryPoints: reference.map((p) => point(p.x, p.y)),
      referenceWidthPx: 400,
      referenceHeightPx: 100,
      homography: homography(IDENTITY),
      mask: mask([1, 1, 1, 1]),
    })
    expect(result.failure).toBe('SUPPORT_EDGE_RATIO')
    expect(result.supportEdgeRatio).toBeCloseTo(30, 9)
  })

  it('accepts exactly the 300 area and exactly the 8 edge-ratio boundaries', () => {
    const area = [point(30, 20), point(60, 20), point(60, 30), point(30, 30)]
    const areaResult = evaluateGeometryObservation({
      referencePoints: area,
      queryPoints: area.map((p) => point(p.x, p.y)),
      referenceWidthPx: 100,
      referenceHeightPx: 100,
      homography: homography(IDENTITY),
      mask: mask([1, 1, 1, 1]),
    })
    expect(areaResult.failure).toBe('NONE')
    expect(areaResult.supportAreaPx2).toBeCloseTo(300, 9)

    const edges = [point(30, 20), point(110, 20), point(110, 30), point(30, 30)]
    const edgeResult = evaluateGeometryObservation({
      referencePoints: edges,
      queryPoints: edges.map((p) => point(p.x, p.y)),
      referenceWidthPx: 200,
      referenceHeightPx: 100,
      homography: homography(IDENTITY),
      mask: mask([1, 1, 1, 1]),
    })
    expect(edgeResult.failure).toBe('NONE')
    expect(edgeResult.supportEdgeRatio).toBeCloseTo(8, 9)
  })
})

describe('T333 median semantics and invalid input', () => {
  it('uses the odd middle and even average of reprojection errors', () => {
    const reference = [point(30, 20), point(90, 20), point(90, 80), point(30, 80), point(60, 50)]
    const offsets = [0, 1, 4, 9, 16]
    const odd = evaluateGeometryObservation({
      referencePoints: reference,
      queryPoints: reference.map((p, i) => point(p.x + offsets[i]!, p.y)),
      referenceWidthPx: 100,
      referenceHeightPx: 100,
      homography: homography(IDENTITY),
      mask: mask([1, 1, 1, 1, 1]),
    })
    expect(odd.medianErrorPx).toBe(4)

    const four = [point(30, 20), point(90, 20), point(90, 80), point(30, 80)]
    const even = evaluateGeometryObservation({
      referencePoints: four,
      queryPoints: four.map((p, i) => point(p.x + [0, 2, 4, 6][i]!, p.y)),
      referenceWidthPx: 100,
      referenceHeightPx: 100,
      homography: homography(IDENTITY),
      mask: mask([1, 1, 1, 1]),
    })
    expect(even.medianErrorPx).toBe(3)
  })

  it('throws a redacted typed error for inconsistent copied point arrays', () => {
    const reference = [point(30, 20), point(90, 20), point(90, 80), point(30, 80)]
    expect(() =>
      evaluateGeometryObservation({
        referencePoints: reference,
        queryPoints: reference.slice(0, 3),
        referenceWidthPx: 100,
        referenceHeightPx: 100,
        homography: homography(IDENTITY),
        mask: mask([1, 1, 1, 1]),
      }),
    ).toThrow(GeometryEvaluationError)
  })
})
